(function($){'use strict';$(document).ready(function(){if(!$('.malisafi-minimalist-wrapper').length){return;}let currentFilters={status:'',property_type:'',county:'',search:''};let currentPage=1;let currentSort='date-desc';let isLoading=false;$('.status-btn').on('click',function(){if(isLoading)return;$('.status-btn').removeClass('active');$(this).addClass('active');currentFilters.status=$(this).data('status');currentPage=1;filterProperties();});$('.filter-select').on('change',function(){if(isLoading)return;const filterType=$(this).data('filter');currentFilters[filterType]=$(this).val();currentPage=1;filterProperties();});let searchTimeout;$('.filter-search-input').on('input',function(){if(isLoading)return;clearTimeout(searchTimeout);const searchValue=$(this).val();searchTimeout=setTimeout(function(){currentFilters.search=searchValue;currentPage=1;filterProperties();},500);});$('.filter-search-btn').on('click',function(){if(isLoading)return;currentFilters.search=$('.filter-search-input').val();currentPage=1;filterProperties();});function filterProperties(){if(isLoading)return;const resultsUrl=$('.malisafi-minimalist-wrapper').data('results-url');if(!resultsUrl){return;}const params=new URLSearchParams();if(currentFilters.status){params.append('status',currentFilters.status);}if(currentFilters.property_type){params.append('type',currentFilters.property_type);}if(currentFilters.county){params.append('county',currentFilters.county);}if(currentFilters.search){params.append('search',currentFilters.search);}if(currentSort&&currentSort!=='date-desc'){params.append('sort',currentSort);}const finalUrl=resultsUrl+(params.toString()? '?'+params.toString():'');window.location.href=finalUrl;}$(document).on('keypress','.filter-search-input',function(e){if(e.which===13){e.preventDefault();$('.filter-search-btn').trigger('click');}});$(document).on('click','.clear-filters',function(){currentFilters={status:'',property_type:'',county:'',search:''};$('.status-btn').removeClass('active');$('.status-btn[data-status=""]').addClass('active');$('.filter-select').val('');$('.filter-search-input').val('');});});})(jQuery);